CREATE OR REPLACE PROCEDURE sp_criar_reserva(p_id_hospede INTEGER,p_checkin DATE,p_checkout DATE,p_valor_diaria NUMERIC) LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM hospedes WHERE id_hospede=p_id_hospede) THEN RAISE EXCEPTION 'Hóspede % não encontrado.',p_id_hospede; END IF; IF p_checkin IS NULL OR p_checkout IS NULL OR p_checkout<=p_checkin THEN RAISE EXCEPTION 'Informe datas válidas: check-out posterior ao check-in.'; END IF; IF p_valor_diaria IS NULL OR p_valor_diaria<=0 THEN RAISE EXCEPTION 'A diária deve ser maior que zero.'; END IF; INSERT INTO reservas(id_hospede,data_checkin,data_checkout,valor_diaria,status) VALUES(p_id_hospede,p_checkin,p_checkout,p_valor_diaria,'ATIVA'); END; $$;
